window.AUTH=window.AUTH||{};window.AUTH["16-1495"]={"d":"16-1495","id":"2017/16-1495","n":"City of Hays, Kansas v. Vogt","briefs":[{"k":"petitioner","label":"Brief of petitioner City of Hays, Kansas","date":"2017-11-13","url":"https://www.supremecourt.gov/DocketPDF/16/16-1495/19596/20171113115202753_16-1495%20ts.pdf","side":"pet","n":65},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2017-11-20","url":"https://www.supremecourt.gov/DocketPDF/16/16-1495/21010/20171120195843784_16-1495UnitedStatestsac.pdf","side":"us","n":60},{"k":"respondent","label":"Brief of respondent Matthew Jack D. Vogt","date":"2017-12-13","url":"https://www.supremecourt.gov/DocketPDF/16/16-1495/23745/20171213160248384_Vogt%20Merits%20Response%20FINAL.pdf","side":"res","n":54},{"k":"reply","label":"Reply of petitioner City of Hays, Kansas","date":"2018-01-08","url":"https://www.supremecourt.gov/DocketPDF/16/16-1495/27064/20180108162230679_16-1495_Reply%20Brief.pdf","side":"pet","n":32}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Arizona v. Fulminanate","cite":"499 U.S. 279","y":1991,"id":"1990/89-839","sc":1,"sum":"The Court held that Fulminante was coerced to confess in violation of the Fifth and Fourteenth Amendments. The Court found that \"it was fear of physical violence, absent protection from his friend Sarivola, which motivated Fulminante to confess.\" This motivation invalidated his confession. Since Fulminante's confession to Donna Sarivola was closely tied to his first coerced confession, the Court dismissed both.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Armour & Co. v. Wantock","cite":"323 U.S. 126","y":1944,"id":"scdb/1944-014","sc":1,"sum":"1. Fireguards employed by a manufacturer of goods for interstate comnerce, held covered by the Fair Labor Standards Act of 1938, as employed in an \"occupation necessary to the production\" of goods for interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Arnett v. Kennedy","cite":"416 U.S. 134","y":1974,"id":"1973/72-1118","sc":1,"sum":"The court held that the procedures established for the purpose of determining whether there is \"cause\" for Kennedy's dismissal satisfied the requirements of procedural due process. The court also held that standard of employment protection imposed by was not impermissibly vague or overbroad in its regulation of the speech of federal employees.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Beck v. Washington","cite":"369 U.S. 541","y":1962,"id":"1961/40","sc":1,"sum":"On the record in this case, petitioner has failed to sustain the burden of showing that his indictment, trial and conviction violated the Due Process or Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Brown v. Walker","cite":"161 U.S. 591","y":1896,"id":"scdb/1895-164","sc":1,"sum":"The provision in the act of February 11, 1893, c. 83, 27 Stat. 443, “that no person shall be excused from attending and testifying or from producing books, papers, tariffs, contracts, agreements, and documents before the Interstate Commerce Commission, or in obedience to the subpoena of the Commission, on the ground or for the reason that the testimony or evidence, documentary or otherwise, required of him may tend …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"1, 5, 16","1":"13, 14","2":"2, 27"}},{"t":"case","label":"Burns v. Reed","cite":"500 U.S. 478","y":1991,"id":"1990/89-1715","sc":1,"sum":"A state prosecuting attorney is absolutely immune from liability for damages under § 1983 for participating in a probable-cause hearing, but not for giving legal advice to the police.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Chavez v. Martinez","cite":"538 U.S. 760","y":2003,"id":"2002/01-1444","sc":1,"ar":3,"sum":"In a 6-3 judgment delivered by Justice Clarence Thomas, the Court held that Chavez did not deprive Martinez of his Fifth Amendment rights. Chief Justice William H. Rehnquist and Justices Sandra Day O'Connor and Antonin Scalia, joined Justice Thomas.","sumSrc":"Oyez","by":{"0":"passim","1":"9, 17, 25","2":"15, 16, 25, 36, 43, 44, 59","3":"14, 20, 21"}},{"t":"case","label":"Counselman v. Hitchcock","cite":"142 U.S. 547","y":1892,"id":"scdb/1891-083","sc":1,"ar":2,"sum":"Under the 5th Amendment to the Constitution of the United States, which declares that “ no person... shall be compelled in any criminal case to be a witness against himself,” where a person is under examination before a grand jury, in an investigation into certain alleged violations of the' interstate commerce act of February 4, 1887, 24 Stat. 379, and the amendatory act of March 2, 1889, 25 Stat. 855, he is not …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13","1":"9","2":"17, 25","3":"9"}},{"t":"case","label":"County of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"sum":"The Court held that Riverside's actions did not comply with the Gerstein precedent. Justice O'Connor argued that it was the state's burden to demonstrate extraordinary circumstances when delaying probable cause determinations beyond 48 hours. The lower court in this case had placed that responsibility on the accused. Intervening weekends or complicated pretrial proceedings were not legitimate reasons for delay.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"County of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Gardner v. Broderick","cite":"392 U.S. 273","y":1968,"id":"1967/635","sc":1,"sum":"If appellant, a policeman, had refused to answer questions directly relating to the performance of his official duties, without being required to waive his immunity with respect to the use of his answers or the fruits thereof in a criminal prosecution of himself, Garrity, supra, the privilege against self-incrimination would not have been a bar to his dismissal. However, his dismissal solely for his refusal to waive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Garner v. United States","cite":"424 U.S. 648","y":1976,"id":"1975/74-100","sc":1,"sum":"Petitioner's privilege against compulsory self-incrimination was not violated. Since petitioner made incriminating disclosures on his tax returns instead of claiming the privilege, as he had the right to do, his disclosures were not compelled incriminations. Here, where there is no factor depriving petitioner of the free choice to refuse to answer, the general rule applies that if a witness does not claim the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Garrity v. New Jersey","cite":"385 U.S. 493","y":1967,"id":"1966/13","sc":1,"ar":7,"sum":"The Court held that the threat of loss of employment constituted coercion in violation of the Fifth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"passim","1":"27","2":"19, 37, 49","3":"14, 21"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"ar":14,"sum":"The Court held that the Fourth Amendment entitles a person arrested without a warrant and charged by information to a timely preliminary hearing on probable cause.","sumSrc":"Oyez","by":{"0":"21, 22, 29","1":"15, 16, 28, 33","2":"21, 24, 39, 54","3":"5"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Hickman v. Taylor","cite":"329 U.S. 495","y":1947,"id":"scdb/1946-035","sc":1,"sum":"Under the Federal Rules of Civil Procedure, plaintiff in a suit in a federal district court against certain tug owners to recover for the death of a seaman in the sinking of the tug filed numerous interrogatories directed to the defendants, including one inquiring whether any statements of members of the crew were taken in connection with the accident and requesting that exact copies of all such written statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Hope v. Pelzer","cite":"536 U.S. 730","y":2002,"id":"2001/01-309","sc":1,"sum":"The Court held that the defense of qualified immunity was precluded at the summary judgment phase of Hope's trial.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"sum":"The Court ruled that the general rule excluding evidence obtained in violation of the Fourth Amendment does not apply to the \"knock-and-announce\" rule.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Hudson v. United States","cite":"522 U.S. 93","y":1997,"id":"1997/96-976","sc":1,"sum":"The Court held that the Double Jeopardy Clause does not apply to non-criminal penalties, even if the purpose of the penalty is to punish the offenders and deter future offenders. Since the first punishment handed down by the OCC - a Federal Banking Agency, not a court - was not a criminal punishment, the subsequent indictments were upheld.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Hurtado v. California","cite":"110 U.S. 516","y":1884,"id":"1850-1900/110us516","sc":1,"ar":1,"sum":"The majority opinion, authored by Matthews, reasoned that the Constitution cannot be locked into static conceptions bound by time and place. The Court also took the position that nothing in the Constitution is superfluous. Since the Fifth Amendment contains both a guarantee of grand jury proceedings and a guarantee of due process, the latter cannot embrace the former.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Jackson v. Denno","cite":"378 U.S. 368","y":1964,"id":"1963/62","sc":1,"sum":"The Court held that the New York procedure did not allow for a reliable determination of whether or not the confessions were voluntary. Because the judge does not rule on the issue and the jury only reports on the ultimate question of guilt or innocence, there is no way to determine whether the jury found he confession voluntary.","sumSrc":"Oyez","by":{"0":"9, 27","2":"54","3":"12"}},{"t":"case","label":"Johnson v. New Jersey","cite":"384 U.S. 719","y":1966,"id":"1965/762","sc":1,"sum":"Petitioners' confessions were offered in evidence by the State in their trial for felony murder, at which they were found guilty and sentenced to death. Their convictions became final six years ago. On collateral attack petitioners now argue that the confessions were inadmissible under Eacobedo v. Illinois, 378 U. S. 478. The New Jersey Supreme Court held that Escobedo did not apply -retroactively.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Kastigar v. United States","cite":"406 U.S. 441","y":1972,"id":"1971/70-117","sc":1,"ar":3,"sum":"The Court found that compelled testimony is legitimate given the grant of immunity. Justice Powell found that the protections of immunity that a congressional statute provided were \"coextensive with the scope of the privilege against self-incrimination\" and \"sufficient to compel testimony over a claim of the privilege.\".","sumSrc":"Oyez","by":{"0":"9, 13, 16, 17","1":"11","2":"3, 28, 39, 40, 41, 52, 53, 56, 58, 59","3":"10"}},{"t":"case","label":"Kingsley v. Hendrickson","cite":"135 S. Ct. 2466","y":2015,"id":"2014/14-6368","sc":1,"sum":"The Court held that a pretrial detainee who brings an excessive force claim need only prove that the use of force in question was objectively unreasonable.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Lawn v. United States","cite":"355 U.S. 339","y":1958,"id":"1957/9","sc":1,"ar":3,"sum":"The Court also held that a copy of a cancelled check obtained at the first indictment did not violate Due Process when prosecutors introduced it into evidence at the second proceeding. The petitioner’s counsel had explicitly waived any objection to that evidence at trial.","sumSrc":"Oyez","by":{"0":"19","1":"10"}},{"t":"case","label":"Lefkowitz v. Cunningham","cite":"431 U.S. 801","y":1977,"id":"1976/76-260","sc":1,"sum":"The statute violated appellee's right to be free of compelled self-incrimination under the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24, 25"}},{"t":"case","label":"Lefkowitz v. Turley","cite":"414 U.S. 70","y":1973,"id":"1973/72-331","sc":1,"sum":"New York statutes' require public contracts to provide that if a contractor refuses to waive immunity or to testify concerning his state contracts, his existing contracts may be canceled and he shall be disqualified from further transactions with the State for five years, and further require disqualification from contracting with public authorities upon a person's failure to waive immunity or answer questions …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"12","2":"21, 49, 59"}},{"t":"case","label":"Malloy v. Hogan","cite":"378 U.S. 1","y":1964,"id":"1963/110","sc":1,"sum":"In a 5-to-4 opinion, the Court held that the Fifth Amendment's exception from compulsory self-incrimination is protected by the Fourteenth Amendment against abridgement by a state. When determining if state officers properly obtained a confession, one must focus on whether the statements were made freely and voluntarily without any direct or implied promised or improper influence.","sumSrc":"Oyez","by":{"0":"1, 13","1":"7, 12","2":"26"}},{"t":"case","label":"Martinez v. City of Oxnard","cite":"337 F.3d 1091","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/337/1091/","by":{"0":"31"}},{"t":"case","label":"Maryland v. Craig","cite":"497 U.S. 836","y":1990,"id":"1989/89-478","sc":1,"sum":"In a 5-to-4 decision, the Court held that the Confrontation Clause of the Sixth Amendment, which guarantees criminal defendants face-to-face meetings with witnesses against them at trial, was not absolute.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Maryland v. Shatzer","cite":"559 U.S. 98","y":2010,"id":"2009/08-680","sc":1,"sum":"The Court held that the ruling in Edwards v. Arizona does not allow for suppression of statements if a substantial period of time between the invoking one's Miranda rights and a second interrogation takes place.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Massiah v. United States","cite":"377 U.S. 201","y":1964,"id":"1963/199","sc":1,"sum":"The Supreme Court held that incriminating statements deliberately elicited by federal agents in the absence of counsel after the proceeding has begun violate the Sixth Amendment. The prosecution could not use these statements as evidence against Massiah. Justice Byron R. White dissented, arguing that the statements should be admitted because they were voluntarily made and not coerced.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"McCarthy v. Arndstein","cite":"266 U.S. 34","y":1924,"id":"scdb/1924-054","sc":1,"sum":"1. The right to examine the bankrupt in a bankruptcy proceeding, for the purpose of obtaining possession of property belonging to his estate, rests wholly upon § 21a of the Bankruptcy Act.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13","1":"13","2":"28"}},{"t":"case","label":"McKune v. Lile","cite":"536 U.S. 24","y":2002,"id":"2001/00-1187","sc":1,"sum":"Joined by Chief Justice William H. Rehnquist and Justice Antonin Scalia, the Court held that the SATP serves a vital penological purpose, and that offering inmates minimal incentives to participate does not amount to compelled self-incrimination prohibited by the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Michigan v. Tucker","cite":"417 U.S. 433","y":1974,"id":"1973/73-482","sc":1,"sum":"Respondent, who had been arrested for rape, was questioned by police. Before the commencement of the interrogation (which antedated this Court's decision in Miranda v. Arizona, 384 U. S. 436), respondent was advised of his right to remain silent and his right to counsel (but not of his right to the appointment of counsel if he was indigent). Respondent related an alibi that he was with a friend (Henderson), at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14","1":"25","2":"26","3":"20"}},{"t":"case","label":"Minnesota v. Murphy","cite":"465 U.S. 420","y":1984,"id":"1983/82-827","sc":1,"ar":1,"sum":"The Supreme Court held that admissions made to a probation officer about a crime unrelated to the probation are admissible in subsequent prosecution. A state may require a probationer to meet with his officer and discuss matters that may affect his probationary status, but this does not create an exception to the rule that one must assert the privilege against self-incrimination.","sumSrc":"Oyez","by":{"0":"13, 14, 17"}},{"t":"case","label":"Miranda v. Arizona","cite":"384 U.S. 436","y":1966,"id":"1965/759","sc":1,"ar":2,"sum":"The Court held that law enforcement cannot use testimony given by anyone under interrogation while in custody without that person being informed of their legal rights.","sumSrc":"Oyez","by":{"0":"11, 13","1":"21","2":"31","3":"21"}},{"t":"case","label":"Mitchell v. United States","cite":"526 U.S. 314","y":1999,"id":"1998/97-7541","sc":1,"sum":"The Court held that in the federal criminal system, a guilty plea does not waive the self-incrimination privilege at sentencing and that a sentencing court may not draw an adverse inference from a defendant's silence in determining facts relating to the circumstances and details of the crime. \"Treating a guilty plea as a waiver of the privilege at sentencing would be a grave encroachment on the rights of defendants,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"16","1":"5, 8, 11, 12","2":"3, 26, 30, 37, 38, 57"}},{"t":"case","label":"Murphy v. Waterfront Comm’n","cite":"378 U.S. 52","y":1964,"id":"1963/138","sc":1,"sum":"One jurisdiction in our federal system may not, absent an immunity provision, compel a witness to give testimony which might incriminate him under the laws of another jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 18","2":"26, 41, 49"}},{"t":"case","label":"New York v. Quarles","cite":"467 U.S. 649","y":1984,"id":"1983/82-1213","sc":1,"sum":"The Court held that there is a \"public safety\" exception to the requirement that officers issue Miranda warnings to suspects. Since the police officer's request for the location of the gun was prompted by an immediate interest in assuring that it did not injure an innocent bystander or fall into the hands of a potential accomplice to Quarles, his failure to read the Miranda warning did not violate the Constitution.","sumSrc":"Oyez","by":{"0":"12, 30","1":"18","2":"36"}},{"t":"case","label":"Oregon v. Elstad","cite":"470 U.S. 298","y":1985,"id":"1984/83-773","sc":1,"sum":"In a 6-to-3 decision, the Court held that while Miranda required that unwarned admissions must be suppressed, subsequent statements, if made knowingly and voluntarily, need not be. The Court held that \". . .the mere fact that a suspect has made an unwarned admission does not warrant a presumption of compulsion.\" The Court also noted that police officers were ill-equipped to determine when \"custody\" legally begins.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Owen v. City of Independence","cite":"445 U.S. 622","y":1980,"id":"1979/78-1779","sc":1,"sum":"A municipality has no immunity from liability under § 1983 flowing from its constitutional violations and may not assert the good faith of its officers as a defense to such liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Slochower v. Board of Higher Ed.","cite":"350 U.S. 551","y":1956,"id":"1955/23","sc":1,"sum":"The Supreme Court held that dismissal of the review motion was improper. §903 is unconstitutional as applied in this case because it denies due process of law. The Court emphasized that invoking the Fifth Amendment does not amount to an admission of guilt.","sumSrc":"Oyez","by":{"0":"23, 24"}},{"t":"case","label":"Spevack v. Klein","cite":"385 U.S. 511","y":1967,"id":"1966/62","sc":1,"sum":"He concluded that the plurality improperly invalidated New York's rules by reversing Spevack's disbarment and determined that protection from disbarment for failure to provide information to a judicial inquiry went beyond the scope of the right against self-incrimination.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Stone v. Powell","cite":"428 U.S. 465","y":1976,"id":"1975/74-1055","sc":1,"sum":"In a 6-to-3 decision, the Court held that where states had provided opportunities for full and fair litigation of Fourth Amendment claims, the Constitution did not require the granting of federal habeas corpus relief. The Court also held that any additional benefits from considering search and seizure claims of state prisoners on collateral review would be small in relation to the costs.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Stump v. Sparkman","cite":"435 U.S. 349","y":1978,"id":"1977/76-1750","sc":1,"sum":"The Court held that a district court judge has the power to entertain and act upon the petition for sterilization, which makes him immune from damages liability even if his approval of the petition was in error.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Uniformed Sanitation Men Ass’n v. Commissioner of Sanitation","cite":"392 U.S. 280","y":1968,"id":"1967/823","sc":1,"sum":"Petitioners as public employees are entitled, like all other persons, to the benefit of the constitutional privilege against self-incrimination and they may not be faced with proceedings which, as here, presented them' with a choice between surrendering their constitutional rights or their jobs. Gardner v. froderick, ante, p. 273. Public employees are subject to dismissal If they +efuse to account for the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"United States v. Calandra","cite":"414 U.S. 338","y":1974,"id":"1973/72-734","sc":1,"ar":3,"sum":"The Supreme Court held that the exclusionary rule does not apply in grand jury proceedings. The purpose of a grand jury is to determine whether a crime was committed and whether to charge someone in connection with that crime. Using the exclusionary rule would interfere with that purpose. The exclusionary rule is also meant to deter police misconduct, not provide a new constitutional right.","sumSrc":"Oyez","by":{"0":"19, 20","1":"10","2":"46"}},{"t":"case","label":"United States v. Hubbell","cite":"530 U.S. 27","y":2000,"id":"1999/99-166","sc":1,"ar":1,"sum":"The Court, in order to determine the precise scope of a grant of immunity with respect to the production of documents in response to a subpoena, held that a person responding to subpoena, pursuant to a court order granting immunity, could not be prosecuted on the basis of information in the documents produced if the government did not have any prior, independent knowledge of the documents.","sumSrc":"Oyez","by":{"0":"1, 18","1":"10, 12","2":"2, 19, 20, 21, 41, 42, 43, 56","3":"17, 18"}},{"t":"case","label":"United States v. Janis","cite":"428 U.S. 433","y":1976,"id":"1975/74-958","sc":1,"sum":"The judicially created exclusionary rule should not be extended to forbid the use in the civil proceeding of one sovereign (here the Federal Government) of evidence illegally seized by a criminal law enforcement agent of another sovereign (here the state government), since the likelihood of deterring law enforcement conduct through such a rule is not sufficient to outweigh the societal costs imposed by the exclusion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 20"}},{"t":"case","label":"United States v. Kordel","cite":"397 U.S. 1","y":1970,"id":"1969/87","sc":1,"sum":"Respondents ire corporate officers who, with the corporation, were convicted of violating the Federal Food, Drug, and Cosmetic Act. An in rem action against two corporate products had been begun in June 1960, and interrogatories routinely prepared by the Food and Drug Administration (FDA) were submitted to the corporation in January 1961. Later that month the corporation and respQndents were notified, pursuant to § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"United States v. Verdugo–Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"0":"passim","1":"4, 6, 17, 25","2":"35","3":"1, 10"}},{"t":"case","label":"United States v. Washington","cite":"431 U.S. 181","y":1977,"id":"1976/74-1106","sc":1,"sum":"Respondent's grand jury testimony may properly be used against him mna subsequent trial. The comprehensive warnings he received, whether or not such warnings were constitutionally required, dissipated any element of compulsion to self-incrimination that might otherwise have been present. The fact that a subpoenaed grand jury witness is a putative or potential defendant neither impairs nor enlarges his constitutional …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13","2":"21"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 22","2":"24, 45, 46"}},{"t":"case","label":"Watkins v. United States","cite":"354 U.S. 178","y":1957,"id":"1956/261","sc":1,"sum":"In a 6-to-1 decision, the Court held that the activities of the House Committee were beyond the scope of congressional power. The Court held that both the authorizing resolution of the Committee and the specific statements made by the Committee to Watkins failed to limit the Committee's power.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Whitley v. Alberts","cite":"475 U.S. 312","y":1986,"id":"1985/84-1077","sc":1,"sum":"During the course of a riot at the Oregon State Penitentiary, a prison officer was taken hostage and placed in a cell on the upper tier of a two-tier cellblock. In an attempt to free the hostage, prison officials worked out a plan that called for the prisoner security manager to enter the cellblock unarmed, followed by prison officers armed with shotguns. The security manager ordered one of the officers to fire a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Withrow v. Williams","cite":"507 U.S. 680","y":1993,"id":"1992/91-1030","sc":1,"sum":"The Supreme Court held that the decision in Stone had been one of prudence rather than one of jurisdiction.","sumSrc":"Oyez","by":{"0":"9, 11, 12","1":"17, 27","2":"26, 30, 36"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"31"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"passim","1":"passim","2":"1, 8, 13","3":"10"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"22","1":"9, 10, 14, 15, 25"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"31"}},{"t":"usc","label":"18 U.S.C. § 6002","url":"https://www.law.cornell.edu/uscode/text/18/6002","stext":{"head":"§6002. Immunity generally","paras":[[0,"Whenever a witness refuses, on the basis of his privilege against self-incrimination, to testify or provide other information in a proceeding before or ancillary to—"],[1,"(1) a court or grand jury of the United States,"],[1,"(2) an agency of the United States, or"],[1,"(3) either House of Congress, a joint committee of the two Houses, or a committee or a subcommittee of either House,"],[0,"and the person presiding over the proceeding communicates to the witness an order issued under this title, the witness may not refuse to comply with the order on the basis of his privilege against self-incrimination; but no testimony or other information compelled under the order (or any information directly or indirectly derived from such testimony or other information) may be used against the witness in any criminal case, except a prosecution for perjury, giving a false statement, or otherwise failing to comply with the order."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/6002?type=usc&year=mostrecent&link-type=html"},"head":"§6002. Immunity generally","tname":"Crimes and Criminal Procedure","by":{"0":"16","2":"40"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"ar":4,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"4","1":"3, 31","2":"48"}},{"t":"rule","label":"Fed. R. Crim. P. 12","url":"https://www.law.cornell.edu/rules/frcrmp/rule_12","subs":["(d)"],"by":{"0":"27"}},{"t":"case","label":"Allen v. Illinois","cite":"478 U.S. 364","y":1986,"id":"1985/85-5404","sc":1,"sum":"Petitioner was charged in an Illinois Circuit Court with committing the crimes of unlawful restraint and deviate sexual assault, and the State filed a petition to have him declared a sexually dangerous person within the meaning of the Illinois Sexually Dangerous Persons Act (Act). Pursuant to the Act, the court ordered petitioner to submit to two psychiatric examinations. At the bench trial on the petition, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 33"}},{"t":"case","label":"Barber v. Page","cite":"390 U.S. 719","y":1968,"id":"1967/703","sc":1,"ar":1,"sum":"Petitioner and one Woods were jointly charged with armed robbery. During the preliminary hearing Woods waived his privilege against self-incrimination and testified, incriminating petitioner. Petitioner's counsel did not cross-examine Woods. When petitioner was tried in Oklahoma seven months later, Woods was in a federal prison in Texas. The State of Oklahoma made no effort to obtain Woods' presence at trial but …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 32","2":"24"}},{"t":"case","label":"Boyd v. United States","cite":"116 U.S. 616","y":1886,"id":"scdb/1885-138","sc":1,"sum":"The 5th section of the act of June 32, 1874, entitled “ An Act to amend the customs revenue laws,” &c., which section authorizes a court of the United States, in revenue cases, on motion of the government attorney, to require the defendant or claimant to produce in court his private books, invoices and papers, or else the allegations of the attorney to b.> taken as confessed: Held, To be unconstitutional and void as …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"11, 12"}},{"t":"case","label":"Brady v. United States","cite":"397 U.S. 742","y":1970,"id":"1969/270","sc":1,"sum":"The Supreme Court held that United States v. Jackson does not require every guilty plea to be overturned when fear of death was a factor in the plea. The voluntariness of the plea is determined by considering all of the relevant circumstances. While Brady may have been partially motivated by a desire to avoid the death penalty, the guilty plea was voluntarily made with the advice of competent counsel.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Brinegar v. United States","cite":"338 U.S. 160","y":1949,"id":"scdb/1948-121","sc":1,"ar":1,"sum":"Petitioner was convicted in a federal district court for a violation of the Liquor Enforcement Act of 1936, on charges of transporting intoxicating liquor into Oklahoma contrary to the laws of that State. He challenged the validity of his conviction because of the use in evidence against him of liquor seized in a search of his automobile without a warrant and allegedly in violation of the Fourth Amendment. At the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28, 33"}},{"t":"case","label":"Coleman v. Alabama","cite":"399 U.S. 1","y":1970,"id":"1969/72","sc":1,"ar":1,"sum":"The Supreme Court held that Reynolds' identification of Coleman and Stephens did not stem from a prejudicial police lineup. The Court also held that the preliminary hearing was a critical stage, so the defendants were constitutionally entitled to counsel. The Court remanded the case to determine whether denying counsel created an unfair prejudice against the defendants.","sumSrc":"Oyez","by":{"1":"33","2":"39, 47","3":"11"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"1":"15","2":"20, 22","3":"3, 18"}},{"t":"case","label":"Cruz v. New York","cite":"481 U.S. 186","y":1987,"id":"1986/85-5939","sc":1,"sum":"Under Bruton v. United States, 391 U. S. 123, a defendant is deprived of his rights under the Confrontation Clause of the Sixth Amendment when his codefendant's incriminating confession is introduced at their joint trial, even if the jury is instructed to consider that confession only against the codefendant. At petitioner's and his brother's joint trial for the felony murder of a gas station attendant, the court …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"25","3":"18"}},{"t":"case","label":"Culombe v. Connecticut","cite":"367 U.S. 568","y":1961,"id":"1960/161","sc":1,"sum":"On all the circumstances of this record, this confession was not voluntary; its admission in evidence deprived petitioner of due process of law in violation of the Fourteenth Amendment; and his conviction must be set aside. Pp. 568-642. 147 Conn. 194, 158 A. 2d 239, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8"}},{"t":"case","label":"Davis v. United States","cite":"328 U.S. 582","y":1946,"id":"scdb/1945-025","sc":1,"sum":"The conviction is affirmed, because this Court cannot say as a matter of law that the. District Court's finding of fact was erroneous. Pp. 593,594.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Dickerson v. United States","cite":"530 U.S. 428","y":2000,"id":"1999/99-5525","sc":1,"sum":"The Court held that Congress cannot legislatively overrule Miranda v. Arizona.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Doe v. United States","cite":"487 U.S. 201","y":1988,"id":"1987/86-1753","sc":1,"sum":"The Court held that a court order to authorize the release of undisclosed foreign bank documents does not violate the Fifth Amendment rights of a citizen who has not yet been indicted by a grand jury.","sumSrc":"Oyez","by":{"1":"10, 22","2":"19, 31"}},{"t":"case","label":"Estelle v. Smith","cite":"451 U.S. 454","y":1981,"id":"1980/79-1127","sc":1,"ar":7,"sum":"After respondent was indicted in Texas for murder, the State announced its intention to seek the death penalty. At an ensuing psychiatric examination, ordered by the trial court to determine respondent's competency to stand trial and conducted in the jail where he was being held, the examining doctor determined that respondent was competent. Thereafter, respondent was tried by a jury and convicted. A separate …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6, 8, 14, 17, 18, 19","2":"3, 38","3":"3, 7"}},{"t":"case","label":"Giordenello v. United States","cite":"357 U.S. 480","y":1958,"id":"1957/549","sc":1,"sum":"The arrest and seizure were illegal, the narcotics should not have been admitted in evidence, and petitioner's conviction must be set aside.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29, 30"}},{"t":"case","label":"Gonzalez v. United States","cite":"553 U.S. 242","y":2008,"id":"2007/06-11612","sc":1,"sum":"The Court held 8-1 that express consent by counsel suffices to permit a magistrate judge to preside over jury selection in a felony trial, stating that such \"scheduling matters\" are among those for which agreement by counsel generally controls. Seven Justices formed the majority opinion written by Justice Anthony Kennedy with Justice Antonin Scalia concurring in the judgment and Justice Clarence Thomas dissenting.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Hiibel v. Sixth Judicial Dist. Court of Nev.","cite":"542 U.S. 177","y":2004,"id":"2003/03-5554","sc":1,"sum":"In a 5-to-4 opinion written by Justice Anthony Kennedy, the Court ruled that the search did not violate the Fourth Amendment because it was based on reasonable suspicion (the police officer was investigating the assault, and Hiibel was nearby) and involved only a minimally intrusive question (his name).","sumSrc":"Oyez","by":{"1":"10","2":"19, 20, 28","3":"17"}},{"t":"case","label":"Hoffman v. United States","cite":"341 U.S. 479","y":1951,"id":"scdb/1950-087","sc":1,"sum":"The conviction is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"28, 49"}},{"t":"case","label":"Melendez-Diaz v. Massachusetts","cite":"557 U.S. 305","y":2009,"id":"2008/07-591","sc":1,"sum":"The Court found that a state forensic analyst's lab report prepared for use in a criminal prosecution is subject to the demands of the Sixth Amendment Confrontation Clause.","sumSrc":"Oyez","by":{"1":"15","2":"25, 54"}},{"t":"case","label":"Pennsylvania v. Ritchie","cite":"480 U.S. 39","y":1987,"id":"1986/85-1347","sc":1,"sum":"The judgment is affirmed in part and reversed in part, and the case is remanded. 509 Pa. 357, 502 A. 2d 148, affirmed in part, reversed in part, and remanded. JUSTICE POWELL delivered the opinion of the Court as to Parts I, II, III-B, III-C, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","3":"1"}},{"t":"case","label":"Piemonte v. United States","cite":"367 U.S. 556","y":1961,"id":"1960/122","sc":1,"sum":"The conviction is sustained. Reina v. United States, 364 U. S. 507. Pp. 556-561. 276 F. 2d 148, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Rothgery v. Gillespie Cnty.","cite":"554 U.S. 191","y":2008,"id":"2007/07-440","sc":1,"ar":1,"sum":"In an 8-1 ruling, the Court held that a criminal defendant's initial appearance before a judge marks the beginning of the proceedings against him and triggers the defendant's Sixth Amendment right to counsel whether or not a prosecutor is aware of or involved in that appearance. This right to counsel applies whenever a defendant learns of the charges against him and has his liberty subject to restriction.","sumSrc":"Oyez","by":{"1":"9, 25","2":"17, 18, 25"}},{"t":"case","label":"Schneckloth v. Bustamonte","cite":"412 U.S. 218","y":1973,"id":"1972/71-732","sc":1,"sum":"The Supreme Court held that whether consent is voluntary can be determined from the totality of the circumstances. It is unnecessary to prove that the person who gave consent knew that he had the right to refuse. The Fourth Amendment protection against unreasonable searches and seizures does not require a knowing and intelligent waiver of constitutional rights.","sumSrc":"Oyez","by":{"1":"17, 27"}},{"t":"case","label":"State v. Washington","cite":"268 P.3d 475","y":2012,"court":"Kan.","url":"https://www.courtlistener.com/c/P.3d/268/475/","by":{"1":"3"}},{"t":"case","label":"Stoot v. City of Everett","cite":"582 F.3d 910","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/582/910/","by":{"1":"31, 32"}},{"t":"case","label":"Ullmann v. United States","cite":"350 U.S. 422","y":1956,"id":"1955/58","sc":1,"sum":"The Act is constitutional and the conviction is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 13, 14","2":"29, 52"}},{"t":"case","label":"United States v. Balsys","cite":"524 U.S. 666","y":1998,"id":"1997/97-873","sc":1,"sum":"In a 7-to-2 decision, the Court held that although resident aliens are entitled to the same Fifth Amendment protections as citizen \"persons\" the risk of their deportation is not sufficient to sustain a self-incrimination privilege intended to apply only to the United States government.","sumSrc":"Oyez","by":{"1":"12, 13, 25"}},{"t":"case","label":"United States v. Blue","cite":"384 U.S. 251","y":1966,"id":"1965/531","sc":1,"sum":"Appellee Was inforined by the Internal Revenue Service in 1962 that he might be prosecuted criminally for violation of federal income tax laws. In 1963 jeopardy assessments were made against him, his wife, and a wholly owned corporation, and all known assets of all three were seized and tax liens recorded. Pursuant to notices giving appellee 90 days in which to file petitions*in the Tax Court contesting the proposed …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"United States v. Friedrick","cite":"842 F.2d 382","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/842/382/","by":{"1":"27"}},{"t":"case","label":"United States v. Garcia","cite":"496 F.2d 670","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/496/670/","by":{"1":"31"}},{"t":"case","label":"United States v. Gecas","cite":"120 F.3d 1419","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/120/1419/","by":{"1":"20, 21, 24","2":"23, 31, 33"}},{"t":"case","label":"United States v. Patane","cite":"542 U.S. 630","y":2004,"id":"2003/02-1183","sc":1,"sum":"Two other justices also held that the physical evidence was constitutionally admissible, but did so with the understanding that the Miranda warnings must be accommodated to other objectives of the criminal justice system. They did not discuss whether the Miranda warnings were, in themselves, constitutionally required.","sumSrc":"Oyez","by":{"1":"12, 17","2":"36"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"sum":"The Court held that the Act was constitutional because when the government's interest in protecting the community outweighs individual liberty, pre-trial detention can be \"a potential solution to a pressing societal problem.\" The Act only applied to a specific list of serious offenses, placed heavy burdens on the government to prove that the arrestee posed significant threats to others, and did not prevent the accused from enjoying a speedy trial.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Williams v. New York","cite":"337 U.S. 241","y":1949,"id":"scdb/1948-087","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment does not require that a person convicted after a fair trial be confronted with and permitted to cross-examine witnesses as to his prior criminal record considered by the judge in accordance with a state statute in determining what sentence to impose pursuant to broad discretion vested in him under state law-even when the jury recommends life imprisonment and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 631","url":"https://www.law.cornell.edu/uscode/text/28/631","by":{"1":"28"}},{"t":"usc","label":"28 U.S.C. § 636","url":"https://www.law.cornell.edu/uscode/text/28/636","subs":["(a)(2)","(b)(1)(A)"],"by":{"1":"29, 29, 29"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","by":{"1":"28"}},{"t":"case","label":"Costello v. United States","cite":"350 U.S. 359","y":1956,"id":"1955/72","sc":1,"sum":"A defendant in a criminal case in a federal court may be required to stand trial and his conviction may be sustained where only hearsay evidence was presented to the grand jury which indicted him.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Davis v. Washington","cite":"547 U.S. 813","y":2006,"id":"2005/05-5705","sc":1,"sum":"The Court ruled that the Confrontation Clause of the Sixth Amendment, as interpreted in Crawford v. Washington , does not apply to \"non-testimonial\" statements not intended to be preserved as evidence at trial. In Hammon's case, however, the Court ruled that Mrs. Hammon's statements to the police were testimonial.","sumSrc":"Oyez","by":{"2":"2, 20"}},{"t":"case","label":"Ferguson v. Georgia","cite":"365 U.S. 570","y":1961,"id":"1960/44","sc":1,"sum":"This application of § 38-415 denied appellant the effective assistance of his counsel at a crucial point in his trial, and it violated the Due Process Clause of the Fourteenth Amendment. Pp. 570-596. 215 Ga. 117, 109 S. E. 2d 44, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22, 31"}},{"t":"case","label":"Halbert v. Michigan","cite":"545 U.S. 605","y":2005,"id":"2004/03-10198","sc":1,"sum":"The Court held that the due process and equal protection clauses required Michigan to provide counsel for defendants who wanted to appeal to the state appellate court.","sumSrc":"Oyez","by":{"2":"47","3":"11"}},{"t":"case","label":"Kalkines v. United States","cite":"472 F.2d 1391","y":1973,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/472/1391/","by":{"2":"51"}},{"t":"case","label":"Lafler v. Cooper","cite":"566 U.S. 156","y":2012,"id":"2011/10-209","sc":1,"sum":"The Court found that the test to determine ineffective assistance of counsel, from Strickland v. Washington, was not properly applied in an aggravated assault case.","sumSrc":"Oyez","by":{"2":"57"}},{"t":"case","label":"Ohio v. Clark","cite":"135 S. Ct. 2173","y":2015,"id":"2014/13-1352","sc":1,"sum":"The Court held that the introduction of a child’s testimony at trial through a teacher does not violate the Confrontation Clause of the Sixth Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Pennsylvania v. Muniz","cite":"496 U.S. 582","y":1990,"id":"1989/89-213","sc":1,"sum":"The Court held that the Fifth Amendment distinguishes between real or physical evidence and testimonial evidence, of which only testimonial evidence is protected under the Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Press-Enterprise Co. v. Superior Court of Cal.","cite":"478 U.S. 1","y":1986,"id":"1985/84-1560","sc":1,"sum":"The Supreme Court held that the First Amendment right of public access applies to preliminary hearings. Closed preliminary hearings are only permissible when specific findings on the record show that closure is essential.","sumSrc":"Oyez","by":{"2":"17, 39, 58","3":"12"}},{"t":"case","label":"United States v. Gouveia","cite":"467 U.S. 180","y":1984,"id":"1983/83-128","sc":1,"sum":"Respondents were not constitutionally entitled to the appointment of counsel while they were in administrative segregation and before any adversary judicial proceedings had been initiated against them.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"United States v. North","cite":"910 F.2d 843","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/910/843/","by":{"2":"56","3":"15"}},{"t":"case","label":"United States v. Palmquist","cite":"712 F.3d 640","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/712/640/","by":{"2":"51"}},{"t":"case","label":"United States v. White","cite":"322 U.S. 694","y":1944,"id":"scdb/1943-110","sc":1,"by":{"2":"49"}},{"t":"case","label":"Waller v. Georgia","cite":"467 U.S. 39","y":1984,"id":"1983/83-321","sc":1,"sum":"The Court held that the Sixth Amendment right to a public trial applied to suppression hearings.","sumSrc":"Oyez","by":{"2":"39","3":"12"}},{"t":"usc","label":"18 U.S.C. § 4244","url":"https://www.law.cornell.edu/uscode/text/18/4244","by":{"2":"38"}},{"t":"rule","label":"Fed. R. Crim. P. 5.1","url":"https://www.law.cornell.edu/rules/frcrmp/rule_5.1","subs":["(d)"],"by":{"2":"55"}},{"t":"rule","label":"Fed. R. Crim. P. 12.2","url":"https://www.law.cornell.edu/rules/frcrmp/rule_12.2","subs":["(c)(4)"],"by":{"2":"38"}},{"t":"case","label":"Best v. City of Portland","cite":"554 F.3d 698","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/554/698/","by":{"3":"2"}},{"t":"case","label":"Digital Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1992,"id":"1993/93-405","sc":1,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Douglas v. California","cite":"372 U.S. 353","y":1963,"id":"1961/34","sc":1,"sum":"The Court held that California’s treatment of defendants changed depending on whether the defendant could afford counsel. Indigent defendants, potentially with “hidden merit” in their appeals, could not meaningfully appeal convictions when courts conducted reviews without input from the defendant’s attorney.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Michigan v. Bryant","cite":"562 U.S. 344","y":2011,"id":"2010/09-150","sc":1,"sum":"The Court held that inquiries of wounded victims concerning the perpetrator are non-testimonial if they objectively indicate that the purpose of the interrogation is to enable police assistance to meet an ongoing emergency, and thus, are not afforded heightened protection.","sumSrc":"Oyez","by":{"3":"18, 20"}},{"t":"case","label":"People v. Melotik","cite":"561 N.W.2d 453","y":1997,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/561/453/","by":{"3":"15"}},{"t":"case","label":"Rayyis v. Superior Court","cite":"35 Cal. Rptr. 3d 12","y":2005,"court":"Cal. Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20Rptr.%203d/35/12/","by":{"3":"15"}},{"t":"case","label":"State v. Butler","cite":"897 P.2d 1007","y":1995,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/897/1007/","by":{"3":"4, 5, 8"}},{"t":"case","label":"State v. Moats","cite":"457 N.W.2d 299","y":1990,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/457/299/","by":{"3":"16"}},{"t":"case","label":"State v. Zimmerman","cite":"660 P.2d 960","y":1983,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/660/960/","by":{"3":"7"}},{"t":"case","label":"Van Cauwenberghe v. Biard","cite":"486 U.S. 517","y":1988,"id":"1987/87-336","sc":1,"sum":"Neither an order denying a motion to dismiss on the ground that an extradited person is immune from civil process, nor an order denying such a motion on forum non conveniens grounds, is a collateral order subject to immediate appeal as a final judgment under § 1291.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Whorton v. Bockting","cite":"549 U.S. 406","y":2007,"id":"2006/05-595","sc":1,"sum":"The Court ruled unanimously \"that Crawford announced a 'new rule' of criminal procedure and that this rule does not fall within the Teague exception for watershed rules.\" Justice Samuel Alito's opinion called the Crawford ruling \"flatly inconsistent\" with the prior precedents that it overruled. It was therefore a new rule of criminal procedure.","sumSrc":"Oyez","by":{"3":"18"}}]};